var e={about:[{key:`hero`,label:`Hero heading`,hint:`The page's top heading and subheading.`,singleton:!0,fields:[`title`,`subtitle`]},{key:`intro`,label:`Introduction`,hint:`The founding-story paragraph, with an optional photo shown beside it.`,singleton:!0,fields:[`body`,`image`]},{key:`approach_intro`,label:`“Our Approach” section heading`,hint:`The heading shown above the four approach cards.`,singleton:!0,fields:[`title`]},{key:`approach_card`,label:`Approach card`,hint:`One of the cards under “Our Approach” (e.g. “Hands-on, project-based learning”).`,singleton:!1,fields:[`icon`,`title`,`body`]},{key:`who_we_work_with_intro`,label:`“Who We Work With” section heading`,hint:`The heading shown above the job seekers / employers columns.`,singleton:!0,fields:[`title`]},{key:`job_seekers_intro`,label:`Job seekers column intro`,hint:`The heading and short intro above the job seekers checklist.`,singleton:!0,fields:[`title`,`body`]},{key:`job_seeker_item`,label:`Job seeker checklist item`,hint:`One line in the job seekers checklist.`,singleton:!1,fields:[`body`]},{key:`employers_intro`,label:`Employers column intro`,hint:`The heading and short intro above the employers checklist.`,singleton:!0,fields:[`title`,`body`]},{key:`employer_item`,label:`Employer checklist item`,hint:`One line in the employers checklist.`,singleton:!1,fields:[`body`]},{key:`cta`,label:`Call-to-action`,hint:`The closing “Ready to get started?” banner and its two buttons.`,singleton:!0,fields:[`title`,`body`,`primary_label`,`primary_url`,`secondary_label`,`secondary_url`]}],contact:[{key:`hero`,label:`Hero heading`,hint:`The page's top heading and subheading.`,singleton:!0,fields:[`title`,`subtitle`]},{key:`get_in_touch`,label:`“Get in touch” block`,hint:`The heading and text shown beside the contact form, with an optional photo. The address/phone/email details themselves come from Settings, not here.`,singleton:!0,fields:[`title`,`body`,`image`]}]};function t(e,t){return(e||[]).find(e=>e.section_key===t)}function n(e,t){return(e||[]).filter(e=>e.section_key===t).sort((e,t)=>e.sort_order-t.sort_order)}export{t as n,n as r,e as t};